    assert_eq!(w(5).wrap("ab verylongword"), ["ab", "verylongword"]);
    assert_eq!(w(12).wrap("verylongword b"), ["verylongword", "b"]);
    assert_eq!(w(14).wrap("verylongword b"), ["verylongword b"]);
    assert_eq!(w(13).wrap("verylongword b"), ["verylongword", "b"]);
