    assert_eq!(w(20).indent(0).unwrap().first_indent(6).unwrap().wrap(FOX), ["      The quick", "brown fox jumps over", "the lazy dog"]);
    assert_eq!(w(20).indent(3).unwrap().wrap(FOX), w(20).indent(3).unwrap().first_indent(3).unwrap().wrap(FOX));
