    assert_eq!(w(80).wrap(" \t\n "), Vec::<String>::new());
    assert_eq!(w(10).wrap("  lots   of\nspace  "), ["lots of", "space"]);
    assert_eq!(w(4).wrap("é é é é é"), ["é é", "é é", "é"]);
}

