    let e: Box<dyn std::error::Error> = Box::new(WrapError::ZeroWidth);
    assert_eq!(e.to_string(), "width must be at least 1");
    let w2 = w(10);
    let again = w2.clone();
    assert_eq!(w2.wrap("x y"), again.wrap("x y"));
}
