fn indent_counts_towards_the_width() {
    assert_eq!(w(20).indent(4).unwrap().wrap(FOX), ["    The quick brown", "    fox jumps over", "    the lazy dog"]);
    assert_eq!(w(20).indent(0).unwrap().wrap(FOX), w(20).wrap(FOX));
    assert_eq!(w(10).indent(8).unwrap().wrap("a bb ccc"), ["        a", "        bb", "        ccc"]);
    let wide = w(12).indent(11).unwrap();
    assert_eq!(wide.wrap("ab c"), ["           ab", "           c"]);
}

#[test]
